export default function dedupeSorted(arr) {
  if (arr.length <= 1) return arr;
  const result = [arr[0]];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] !== arr[i-1]) {
      result.push(arr[i]);
    }
  }
  return result;
}

