import { spawn } from 'node:child_process';
import { promises as fs } from 'node:fs';
import { join } from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    // Read the pinned test cases
    const testCasesPath = join(referenceDir, 'pinned-test-cases.txt');
    const testCases = await fs.readFile(testCasesPath, 'utf-8');

    // Create a test runner that imports the submission and runs all pinned cases
    const testRunnerCode = `
import assert from 'node:assert/strict';
import { dedupeSorted } from '${join(submissionDir, 'answer.mjs')}';
import { test } from 'node:test';

${testCases}
`;

    const testRunnerPath = join(referenceDir, 'test-runner.mjs');
    await fs.writeFile(testRunnerPath, testRunnerCode);

    // Execute the test runner and capture output
    return new Promise((resolve) => {
      const proc = spawn(process.execPath, [testRunnerPath], {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 10000
      });

      let stdout = '';
      let stderr = '';
      let testsPassed = 0;
      let testsFailed = 0;

      proc.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        // Parse test results from node:test output
        // node:test reports pass/fail in structured format
        const passMatch = stdout.match(/tests (\d+) pass/i);
        const failMatch = stdout.match(/tests (\d+) fail/i);

        testsPassed = passMatch ? parseInt(passMatch[1]) : 0;
        testsFailed = failMatch ? parseInt(failMatch[1]) : 0;

        // Check if all tests passed (code 0 and no failures reported)
        const allPassed = code === 0 && testsFailed === 0 && testsPassed > 0;

        if (allPassed) {
          resolve({
            accept: true,
            reason: `All ${testsPassed} pinned test cases passed. Submission correctly removes consecutive duplicates from sorted arrays.`
          });
        } else if (code !== 0 || testsFailed > 0) {
          resolve({
            accept: false,
            reason: `Test execution failed: ${testsFailed} failures, exit code ${code}. stderr: ${stderr.slice(0, 200)}`
          });
        } else {
          resolve({
            accept: false,
            reason: `No tests executed or results unclear. stdout: ${stdout.slice(0, 200)}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
      });
    });
  } catch (err) {
    return {
      accept: false,
      reason: `Gate execution error: ${err.message}`
    };
  }
}

