            accept: false,
            reason: `Expected ${EXPECTED_TESTS} tests to pass, but only ${testsPassed} passed. Submission may have terminated test execution early.`
          });
        } else {
          resolve({
            accept: false,
            reason: `Test results unclear. stdout: ${stdout.slice(0, 300)}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
      });
    });
  } catch (err) {
